def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # {key: (value, write_time)}
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op

            # Remove expired entries
            expired_keys = [k for k, (v, wt) in cache.items() if wt + ttl <= t]
            for k in expired_keys:
                del cache[k]

            # If key doesn't exist and cache is at capacity, evict LRU
            if key not in cache and len(cache) >= capacity:
                lru_key = next(iter(cache))
                del cache[lru_key]

            # Put the new entry and move to end (most recently used)
            if key in cache:
                del cache[key]
            cache[key] = (value, t)

        elif op[0] == 'get':
            _, t, key = op

            # Remove expired entries
            expired_keys = [k for k, (v, wt) in cache.items() if wt + ttl <= t]
            for k in expired_keys:
                del cache[k]

            # Get the value
            if key in cache:
                value, wt = cache[key]
                # Move to end (most recently used)
                del cache[key]
                cache[key] = (value, wt)
                results.append(value)
            else:
                results.append(-1)

    return results

